INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-01', 'investment', true, '業務職缺的到職說明', '我應徵展場設備業務，面試在一間裝潢新穎的辦公室。人資帶我認識業務部經理，他說公司制度完整，新人都有專人帶。談到薪資時，他說這個職位沒有底薪，收入來自佣金和分紅，只要自己先投入約五萬元參與跑單，第一個月就能回本。他把試算表推到我面前，說今天辦好才保留名額，下週一就能上線。他說不少新人第一週就賺回來了。我手機開著網路銀行的轉帳頁。', '[{"tag": "greed", "text": "說先投入約五萬元參與跑單，第一個月就能回本"}, {"tag": "authority", "text": "由自稱業務部經理的人出面保證公司制度完整"}, {"tag": "time_pressure", "text": "說今天辦好才保留名額"}]'::jsonb, 2, '{77}'::bigint[], '改編自：165 反詐騙宣導案例「畢業求職要慎選 誤入詐騙心生怨」（假求職轉投資詐騙）', NULL, 'published', 'exam_message', 'investment-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-02', 'investment', true, '線上課程後的帳戶出金', '我上完一堂免費的股市線上課程，助教說可以用優惠方式買海外股票組合，拉我進操盤群，在他介紹的平台開戶。三週來帳面一直漲，投入的約十八萬元已經變成三十多萬。我按下出金，客服說依規定要先另外繳兩成稅金，不能從獲利裡扣，繳完才撥款。上次他們要的是保證金，這已經是第二次補錢。客服傳來新的帳戶，說今天下班前要入帳。', '[{"tag": "greed", "text": "帳面三週從十八萬漲到三十多萬"}, {"tag": "authority", "text": "客服說依規定要先另外繳兩成稅金才撥款"}, {"tag": "time_pressure", "text": "要求今天下班前把稅金匯進新的帳戶"}]'::jsonb, 3, '{70}'::bigint[], '改編自：165 打詐儀錶板「假投資詐騙」常見手法清單', NULL, 'published', 'exam_message', 'investment-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-04', 'investment', true, '聊了兩個月的投資話題', '交友軟體上認識的他說自己是外派中東的工程人員，兩個月來每天傳訊息問我吃飯了沒，視訊總是說訊號不好，幾秒就斷。他說有一檔海外債券每月配息很穩，他投了半年已經回本，是在當地銀行上班的朋友給的內部額度。上週我投了約六萬元，平台顯示配息正常。今天我想領回本金，平台說要先繳一筆境外查核費，他說願意幫我出一半。', '[{"tag": "trust_building", "text": "每天傳訊息關心作息，視訊總說訊號不好就掛斷"}, {"tag": "greed", "text": "說海外債券每月配息很穩，他已經回本"}, {"tag": "authority", "text": "說額度是當地銀行上班的朋友給的內部名額"}]'::jsonb, 2, '{69}'::bigint[], '改編自：165 打詐儀錶板「假交友（投資詐財）詐騙」常見手法清單', NULL, 'published', 'exam_message', 'investment-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-05', 'investment', true, '電子股的新股申購', '我在理財論壇看到一則新股申購的分享，加入作者開的群組，群裡每天有人貼中籤通知和入帳畫面。今天助理私訊恭喜我抽中一檔電子零組件公司的新股，價格比市價低兩成，還傳來一張蓋著金融機構章的通知。她說收盤前要把約九萬元匯到一個新的個人帳戶完成認股，逾時會留下違約紀錄。她還說名額是金融機構特別保留的。我盯著那張通知上的帳號。', '[{"tag": "social_proof", "text": "群裡每天有人貼中籤通知和入帳畫面"}, {"tag": "authority", "text": "傳來蓋著金融機構章的中籤通知"}, {"tag": "greed", "text": "說抽中的新股比市價低兩成"}, {"tag": "time_pressure", "text": "收盤前沒匯款就會留下違約紀錄"}]'::jsonb, 2, '{76}'::bigint[], '改編自：165 打詐儀錶板「私募跟單勿上鉤 被當韭菜真的嘔」與金管會新聞稿「網路投資群組詐騙多，停看聽後再投資」', NULL, 'published', 'exam_message', 'investment-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-07', 'investment', true, '自動交易服務的升級', '理財社團有人轉傳一支自動交易服務的說明影片，我照著下載 App，放了兩萬元進去。幾天後畫面顯示資產增加，我也成功領回一小筆，到帳很快。客服說升級成專業會員就能用更快的交易模型，但伺服器今晚維護前只剩幾個名額，要把約十二萬元現金交給外派專員，約在車站附近的速食店。他還提醒我，銀行如果問用途，就說是家用，不要多講。', '[{"tag": "trust_building", "text": "先讓你成功領回一小筆"}, {"tag": "greed", "text": "說升級專業會員就能用更快的交易模型"}, {"tag": "time_pressure", "text": "說伺服器今晚維護前只剩幾個名額"}]'::jsonb, 3, '{76}'::bigint[], '改編自：165 打詐儀錶板「私募跟單勿上鉤 被當韭菜真的嘔」與165 全民防騙網假投資通報', NULL, 'published', 'exam_message', 'investment-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-09', 'investment', true, '盤前的兩檔觀察名單', '我在通勤廣播聽到一段節目，介紹下一季的產業觀察清單，最後說想拿完整清單可以加助理的帳號。我照節目說的加了助理之後，助理說清單上的公司一季能漲一倍，只有今晚登記的人能加入帶單，要先匯約一萬元學費到她的帳戶，沒漲到就退費。她說清單要付款後才給看。我問能不能先看其中一檔，她說付款前都不能給。我正在看她傳來的付款說明。', '[{"tag": "greed", "text": "說清單上的公司一季能漲一倍"}, {"tag": "time_pressure", "text": "說只有今晚登記的人能加入帶單"}]'::jsonb, 1, '{70}'::bigint[], '改編自：數位發展部網路詐騙通報查詢網已確認之詐騙訊息，已去識別化', NULL, 'published', 'exam_message', 'investment-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-10', 'investment', true, '交易額度的啟用通知', '我在海外期貨交易服務的線上說明會填了試用申請，一位接待員幫我完成帳號設定。今天他傳來一張核准頁，說可以啟用約十萬元的交易額度，跟我自己的錢一起操作。他說要先把一成保證金匯到助理的個人帳戶，今天沒付就取消。我問能不能從自己的期貨帳戶扣，他說不行，這個額度要另外處理。我正在核對收款人的名字，還沒按下轉帳。', '[{"tag": "greed", "text": "說可以啟用約十萬元的交易額度"}, {"tag": "time_pressure", "text": "說保證金今天沒付，額度就取消"}]'::jsonb, 2, '{76}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'investment-10', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-11', 'investment', true, '玻璃藝術品的收藏計畫', '我在工藝展後加入一個玻璃藝術品收藏群，顧問介紹一批作者簽名的限量作品，說買下後交給公司出租給飯店展示，每年保證有百分之十二的租金分潤。我說想先看作品，他說作品已經送到飯店，不方便看。他要我今天先把約六萬元匯到助理的帳戶，才排得進這一批。我問能不能簽約再付，他說合約付款後一起寄給我。我正在看那個匯款頁。', '[{"tag": "greed", "text": "說每年保證有百分之十二的租金分潤"}, {"tag": "time_pressure", "text": "要我今天先匯款才排得進這一批"}]'::jsonb, 3, '{70}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'investment-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-03', 'investment', true, '外匯跟單的提領手續', '我看完一場理財直播，加入主持人開的討論群，群裡每天都有人貼對帳單和獲利截圖，底下一片道謝。我跟著群裡的建議做外匯，前後投了約十二萬元，帳面已經翻倍。今天想提領，平台說要先繳提領金額兩成的保證金才能解鎖。主持人私訊我，說今天之內辦好，才不會影響下一輪布局。我停在提領頁，看著那筆保證金的金額，還沒決定。', '[{"tag": "social_proof", "text": "群裡每天有人貼對帳單和賺錢截圖"}, {"tag": "time_pressure", "text": "說保證金要今天之內辦好"}]'::jsonb, 2, '{76}'::bigint[], '改編自：165 反詐騙宣導案例「私募跟單勿上鉤 被當韭菜真的嘔」（假投資詐騙）', NULL, 'published', 'exam_tactics', 'investment-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-12', 'investment', true, '老茶餅的限量收藏組', '收藏群組傳來一則限量老茶餅的訊息，說全台只釋出約兩千組，協會專家已經分走一千多組，群友也預訂了三百組。訊息附上一張協會顧問的合照，說明年轉售每組可以多賺數萬元。發訊的人說今晚就要封單，要先付約七萬元才能列入名冊，款項匯到他家人的帳戶。我問倉庫在哪、有沒有保管契約，他只說名冊上的人都是老客戶，從來沒人問這個。', '[{"tag": "social_proof", "text": "說專家分走一千多組，群友也預訂三百組"}, {"tag": "authority", "text": "附上協會顧問的合照"}, {"tag": "greed", "text": "說明年轉售每組可以多賺數萬元"}, {"tag": "time_pressure", "text": "說今晚就要封單，先付款才能列名"}]'::jsonb, 2, '{76}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_tactics', 'investment-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-06', 'investment', true, '教育金講座後的方案說明', '我參加一場子女教育金規劃的線上講座，主講人說自己在金融業服務多年，投影片放著證照照片。聊天室不斷有家長說已經加入，也有人貼出每月配息的畫面。會後一位顧問私訊我，說海外教育金方案本金放滿半年，就能每月領固定回饋，今天登記再送一筆迎新金。他說名額今晚重新分配，要保留得先匯約四萬元到助理的帳戶。我看著私訊裡的帳號。', '[{"tag": "authority", "text": "主講人投影片放著證照照片，自稱金融業資歷"}, {"tag": "social_proof", "text": "聊天室不斷有家長說已經加入"}, {"tag": "greed", "text": "本金放滿半年就能每月領固定回饋"}, {"tag": "time_pressure", "text": "名額今晚重新分配，要先匯款保留"}]'::jsonb, 3, '{70}'::bigint[], '改編自：165 全民防騙網假投資通報與金管會新聞稿「網路投資群組詐騙多，停看聽後再投資」', NULL, 'published', 'exam_scenario', 'investment-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-scam-08', 'investment', true, '同事分享的海外債券', '以前的同事把我拉進一個債券認購群，說有一家物流業公司發行半年到期的債券，利息比定存高出不少，由他認識的高階經理保留了一批額度。群裡有人上傳存摺入帳的截圖。承辦人說這批不走證券商或銀行下單，要在銀行下班前把認購款匯到他的帳戶，沒入帳就換下一位。同事說他自己也買了兩張，上一期已經領到利息。我正在看承辦人傳來的帳號。', '[{"tag": "social_proof", "text": "群裡有人上傳存摺入帳截圖"}, {"tag": "authority", "text": "說額度是高階經理保留的"}, {"tag": "greed", "text": "利息比定存高出不少"}, {"tag": "time_pressure", "text": "銀行下班前沒入帳就換下一位"}]'::jsonb, 2, '{70}'::bigint[], '改編自：165 全民防騙網假投資通報與金管會新聞稿「網路投資群組詐騙多，停看聽後再投資」', NULL, 'published', 'exam_scenario', 'investment-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-02', 'shopping', true, '桌遊擴充盒的交易頁面', '我在桌遊同好社團徵求一盒限量擴充，有賣家私訊說手上剛好有，價格也合理。他傳來一個店到店寄件服務的交易頁面連結，要我在上面下單付款。我以前用過類似的服務，畫面看起來也差不多。付款後頁面跳出帳戶異常，要我加客服好友。客服說要照指示操作網路銀行、輸入一組數字重新啟用帳戶，不會扣款。賣家一直提醒我有人在等，動作要快。', '[{"tag": "authority", "text": "傳來看似店到店寄件服務的交易頁"}, {"tag": "trust_building", "text": "頁面和以前用過的服務很像，讓你放心"}, {"tag": "time_pressure", "text": "賣家一直說有人在等，要你動作快"}]'::jsonb, 2, '{74}'::bigint[], '改編自：165 反詐騙宣導案例「誤入詐騙戰鬥盤 積蓄慘遭爆裂衝擊」（網路購物詐騙）', NULL, 'published', 'exam_message', 'shopping-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-03', 'shopping', true, '台中小兩房的租屋訂金', '轉職搬家前，我在租屋社團看到台中一間小兩房，租金比附近行情低一些，照片明亮，條件寫得很清楚。我私訊後，自稱房東代理人的人很親切，問什麼都回得很詳細，還傳來屋內影片。他說房東人在國外，沒辦法帶看，今天已經有三組人在問，如果我真的有意願，得先付一個月租金當訂金，他才幫我把房子保留下來。我正在看他給的帳號。', '[{"tag": "greed", "text": "租金比附近行情低一些"}, {"tag": "trust_building", "text": "代理人很親切，回得很詳細還傳影片"}, {"tag": "time_pressure", "text": "說今天有三組人在問，要先付訂金保留"}]'::jsonb, 2, '{75}'::bigint[], '改編自：165 反詐騙宣導案例「租房找屋勿心急 匯款之前停看聽」（假廣告詐騙）', NULL, 'published', 'exam_message', 'shopping-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-04', 'shopping', true, '搬家出清的平板電腦', '我在社群買賣社團看到一台平板電腦，賣家說搬家整理要出清，價格比行情便宜了快三成。我私訊問能不能面交，他說住在台南，我在台北，沒辦法約。我問能不能走平台的購物車，他說社團最近查得很嚴，怕交易被檢舉下架，要我直接轉帳，付款當天就寄出。他說還有好幾個人在問，再等下去就要賣給別人了。他還傳了開機畫面的照片給我。我正在看他給的帳號。', '[{"tag": "greed", "text": "價格比行情便宜快三成"}, {"tag": "time_pressure", "text": "說再等下去就要賣給別人"}]'::jsonb, 1, '{17}'::bigint[], '改編自：165 宣導「社群買賣詐騙手法詳解」之假賣家詐騙段落', NULL, 'published', 'exam_message', 'shopping-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-06', 'shopping', true, '開學前的刺繡布包', '孩子快開學了，我在社群上看到一家工作室的客製刺繡姓名布包，作品照片很可愛。我私訊店家，他們很快傳來布料樣式和刺繡草圖，連字體都幫我挑好了。店家說客製品一旦排入製作就不能退，開學前的刺繡排程只剩一個空檔，要我今晚把全額匯到負責人的個人帳戶才排得進去。對話紀錄裡只有她私人帳號的名字。我問有沒有訂單編號或取貨地址，他說做好再給我。', '[{"tag": "trust_building", "text": "很快傳來布料樣式與刺繡草圖"}, {"tag": "time_pressure", "text": "說只剩一個空檔，要你今晚全額匯款"}]'::jsonb, 3, '{17}'::bigint[], '改編自：165 全民防騙網「網路購物遇到詐騙了？」與團隊整理的正規流程說明「正規電商交易與退換貨流程」', NULL, 'published', 'exam_message', 'shopping-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-09', 'shopping', true, '運動服包裹的稅費通知', '我上週在海外網站買了運動服，今天收到一則簡訊，寄件名稱很像國際快遞公司，說包裹在海關暫扣，要繳約兩百元稅費才能放行，附了一個付款頁。付款頁列出好幾則收件人剛完成繳費的通知，要我輸入完整卡號、有效期限和簡訊驗證碼。旁邊的客服視窗說逾時包裹就會退運。我記得那個網站有寫運費含稅，但金額不大，我想說付了比較快。我正在付款頁輸入卡號。', '[{"tag": "authority", "text": "簡訊寄件名稱很像國際快遞公司"}, {"tag": "social_proof", "text": "付款頁列出好幾則剛完成繳費的通知"}, {"tag": "time_pressure", "text": "客服視窗說逾時包裹就會退運"}]'::jsonb, 1, '{74}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已移除真實連結', NULL, 'published', 'exam_message', 'shopping-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-10', 'shopping', true, '掃地機器人的訂單郵件', '我收到一封購物平台的訂單郵件，內容是一台約一萬兩千元的掃地機器人，寫著宅配到管理室，付款人和收貨人都是我。我不記得下過這筆單，點了郵件裡的小助手詢問。自稱訂單管理人員的人說是系統錯誤，要我半小時內去買等額的遊戲點數，把序號交給他，才能取消訂單，處理完兩筆錢都會退回。他說不處理的話，明天就會從我的卡扣款。', '[{"tag": "authority", "text": "自稱訂單管理人員，說是系統錯誤"}, {"tag": "time_pressure", "text": "要你半小時內買點數交出序號"}]'::jsonb, 2, '{74}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'shopping-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-11', 'shopping', true, '上班族的膳食纖維方案', '我在廣告上看到給久坐上班族的膳食纖維粉，私訊後客服說吃七天腸胃就會明顯改善。她說今天可以用市價六折買三個月份，約八千元，沒效全額退，這個價格只到今晚。我說想先看看商品頁，她說這款只在私訊賣，沒有商品頁。我問成分和退費條件寫在哪裡，她說先匯款到她的帳戶，再把說明寄給我。我看著她傳來的帳號，還在猶豫要不要買。', '[{"tag": "greed", "text": "說吃七天腸胃就會明顯改善"}, {"tag": "time_pressure", "text": "說六折的價格只到今晚"}]'::jsonb, 3, '{17}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'shopping-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-12', 'shopping', true, '會員抽獎的中獎通知', '我最近在購物平台參加會員抽獎，今天收到一則簡訊，說我在這次活動抽中了約兩千元的獎金，要點連結領取。連結打開是一個領獎頁，要我先登入網路銀行，在十分鐘內轉一元到指定帳戶做驗證，獎金才會撥進來。簡訊裡的網址是一串看不懂的英文，不是平台的網址。我回到平台的 App，沒有看到這則通知。我正在輸入網銀的帳號。', '[{"tag": "greed", "text": "說抽中約兩千元的獎金"}, {"tag": "time_pressure", "text": "要十分鐘內完成帳戶驗證"}]'::jsonb, 2, '{74}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'shopping-12', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-01', 'shopping', true, '限量造型道具的私下交易', '我在遊戲玩家社團徵求一款限量造型道具，有位玩家私訊說他剛好有一套，可以轉給我。我們加了通訊軟體，他拉進一個自稱遊戲交易管理員的帳號。管理員說道具轉讓前要先匯約三千元開通金流，還要我把銀行的簡訊驗證碼念給他。那位玩家一直催，說今天沒辦好就轉給別人。我正在看管理員傳來的帳號，手機剛好跳出一則銀行驗證碼。', '[{"tag": "authority", "text": "自稱遊戲交易管理員，要先匯款開通金流"}, {"tag": "time_pressure", "text": "說今天沒辦好就轉給別人"}]'::jsonb, 1, '{73}'::bigint[], '改編自：165 反詐騙宣導案例「誤認完成交易任務 其實觸發詐騙副本」（虛擬遊戲詐騙）', NULL, 'published', 'exam_tactics', 'shopping-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-07', 'shopping', true, '語言課程的續費通知', '我收到一封語言學習訂閱服務的續費郵件，商標和我用過的服務很像，說試用期本週五晚上結束，之後會扣半年的費用。我點了郵件裡的取消按鈕，線上專員說要取消，得先買等額的數位點數做身分確認，完成後會連同半年費用一起退回。他要我保持通話，把點數序號一張一張念給他。他說試用期一過就退不回來了。我已經走到超商門口。', '[{"tag": "authority", "text": "郵件商標和用過的服務很像"}, {"tag": "time_pressure", "text": "說試用期本週五晚上結束就扣半年費用"}]'::jsonb, 3, '{74}'::bigint[], '改編自：Cofacts 真的假的民眾回報訊息原文，已移除真實連結與帳號', NULL, 'published', 'exam_tactics', 'shopping-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-05', 'shopping', true, '換季促銷的空氣清淨機', '我在社群廣告點進一個購物網站，換季促銷的空氣清淨機只要市面價格的一半，還加送一組替換濾網，商品下面排滿五星評價，不少留言附了開箱照。下單後客服私訊我，說刷卡系統正在維護，今天的折扣訂單要改用轉帳才會成立，要我匯到他給的個人帳戶，庫存只幫我保留十五分鐘。他說轉帳後馬上傳出貨單號給我，我正在看那個帳號。', '[{"tag": "greed", "text": "只要市面價格的一半，還加送濾網"}, {"tag": "social_proof", "text": "商品下排滿五星評價與開箱照"}, {"tag": "authority", "text": "說刷卡系統維護，要改用轉帳"}, {"tag": "time_pressure", "text": "說庫存只保留十五分鐘"}]'::jsonb, 2, '{74}'::bigint[], '改編自：165 全民防騙網「網路購物遇到詐騙了？社群買賣詐騙手法詳解」與數位發展部網路詐騙通報查詢網', NULL, 'published', 'exam_scenario', 'shopping-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-scam-08', 'shopping', true, '溫泉旅宿的團購方案', '朋友轉傳一則宜蘭溫泉旅宿的團購貼文，寒假週末一晚含早餐，價格大約是訂房平台的一半。我私訊小編，他說房間不走訂房系統，要把全額匯給合作的收款窗口，十分鐘內沒入帳就交給候補。他說這是內部名額，所以官網查不到這個價格。我搜尋旅宿的名稱，只找到名字很像的店家，電話也和貼文不一樣。我看著收款的戶名，還在想要不要匯過去。', '[{"tag": "greed", "text": "價格大約是訂房平台的一半"}, {"tag": "time_pressure", "text": "說十分鐘內沒入帳就交給候補"}]'::jsonb, 2, '{17}'::bigint[], '改編自：Cofacts 真的假的民眾回報訊息原文，已去除真實店家與連結', NULL, 'published', 'exam_scenario', 'shopping-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-01', 'fake-sale', true, '直播間的二手機械錶', '我滑到一個二手機械手錶的直播，主播說這批是海外倉庫清算的貨，價格只有市面的幾分之一。我看上一支錶，主播說是老牌子，盒子和說明書都還在。我私訊主播，他給了一個私人帳號，要我先匯約三千元訂金保留，說直播結束後就不是這個價格了。我問能不能走平台付款，他說平台會抽成，價格就不是這個了。我正在看他給的那個私人帳號。', '[{"tag": "greed", "text": "說是海外倉庫清算貨，只要市面幾分之一"}, {"tag": "time_pressure", "text": "說直播結束後就不是這個價格"}]'::jsonb, 2, '{29,68}'::bigint[], '改編自：165 全民防騙網「民眾通報高風險業者」（假網路拍賣）與 165 打詐儀錶板網路購物手法', NULL, 'published', 'exam_message', 'fake-sale-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-10', 'fake-sale', true, '工作室結束營業的出清', '我在攝影器材社團看到一則工作室結束營業的出清，三腳架和攝影燈都只要幾百元，照片裡的器材都很新。我私訊賣家，他說倉庫點交的期限快到了，要我立刻把全額匯到他親友的帳戶，備註不要寫商品名稱。我問能不能去看貨，他說器材都打包好了，沒時間約，也不能先拆開拍照給我看。付款以後才會給我寄件資料。我正在看他給的那個帳號。', '[{"tag": "greed", "text": "三腳架和攝影燈都只要幾百元"}, {"tag": "time_pressure", "text": "說點交期限快到，要立刻匯全額"}]'::jsonb, 1, '{68}'::bigint[], '改編自：數位發展部網路詐騙通報查詢網已確認之詐騙訊息，已去識別化', NULL, 'published', 'exam_message', 'fake-sale-10', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-02', 'fake-sale', true, '二手平板的寄件與收款', '我在拍賣平台賣一台二手平板，買家談得很順，指定要用店到店寄件服務。他說已經付款了，傳來一個寄件服務的客服連結。客服說我是賣家，卻還沒啟用賣家收款功能，買家的錢被凍結了，要我提供銀行資訊，照指示在網路銀行完成收款設定。客服還說款項凍結超過時限就會自動退回買家，要我盡快。買家也傳訊息問我處理好了沒，說他急著要用。我打開網路銀行。', '[{"tag": "trust_building", "text": "買家談得很順，主動指定寄件方式"}, {"tag": "authority", "text": "客服連結說你還沒啟用賣家收款功能"}, {"tag": "time_pressure", "text": "說款項凍結超過時限就會退回買家"}]'::jsonb, 2, '{31,39}'::bigint[], '改編自：165 全民防騙網「民眾通報高風險業者」（假網路拍賣）與刑事局宣導之假買家假物流手法', NULL, 'published', 'exam_message', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-04', 'fake-sale', true, '限量掌上遊戲機的面交', '我在拍賣社團看到一台限量的掌上遊戲機，價格比市面便宜不少。賣家先一口答應面交，約在市區外圍的工業區，可是他說輪班時間一直改，前後改了三次都沒約成。我問能不能走平台下單，他說平台手續費太高，私下比較省。後來他說乾脆我先匯款，他直接寄。他前後給了三個不同銀行的帳號，說哪個方便就匯哪個。我正在看那三個帳號。', '[{"tag": "greed", "text": "限量遊戲機價格比市面低不少"}, {"tag": "trust_building", "text": "先一口答應面交，再一直改時間"}]'::jsonb, 2, '{30,68}'::bigint[], '改編自：165 全民防騙網「民眾通報高風險業者」（假網路拍賣）與 165 打詐儀錶板網路購物手法', NULL, 'published', 'exam_message', 'fake-sale-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-03', 'fake-sale', true, '短影音廣告的展示機出清', '我在短影音廣告看到高階咖啡機的展示機出清，價格低到讓我愣了一下。點開後是一個做得很漂亮的單頁網站，頁面上方寫著限時限量，旁邊有個倒數的時鐘一直在跳。我往下找，看不到公司的名字和統一編號，也沒有客服電話和退貨的說明。我搜尋這個網站的名字，什麼都查不到。我填完訂購表單，頁面說只能轉帳付款。我正在看那個轉帳帳號。', '[{"tag": "greed", "text": "高階咖啡機價格低到讓人愣一下"}, {"tag": "time_pressure", "text": "頁面寫限量，計時器一直在跳"}]'::jsonb, 1, '{32,68}'::bigint[], '改編自：165 全民防騙網「民眾通報高風險業者」（假網路拍賣）與 165 打詐儀錶板網路購物手法', NULL, 'published', 'exam_message', 'fake-sale-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-07', 'fake-sale', true, '劇迷社團的舞台劇門票', '我在劇迷交流社團徵一張舞台劇門票，有人私訊說朋友臨時不能去，可以原價轉讓。他傳來購票紀錄的局部截圖，社團裡也有幾個帳號留言說曾經跟他交易，取票很順利。電子票還沒轉到我的帳號，他就要我先付一半訂金，給了一個和截圖姓名不同的收款戶名，說十分鐘內沒收到就交給下一位。他說戶名是他朋友的，票也是朋友買的。我正在看那個戶名。', '[{"tag": "trust_building", "text": "傳來購票紀錄的局部截圖"}, {"tag": "social_proof", "text": "社團有帳號留言說跟他交易很順利"}, {"tag": "time_pressure", "text": "說十分鐘內沒收到就交給下一位"}]'::jsonb, 3, '{32,68}'::bigint[], '改編自：Cofacts 真的假的民眾回報訊息原文，已去除帳號與連結', NULL, 'published', 'exam_message', 'fake-sale-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-09', 'fake-sale', true, '露營裝備出租的實名確認', '我在常用的租賃平台接了一筆露營裝備出租的單，客人傳來押金付款的截圖，說平台的租賃管理中心要先幫我做實名確認才能撥款。我照他給的方式聯絡客服，客服說不處理的話，會凍結我的銀行帳戶來賠給客人。我問為什麼不在原本的 App 裡處理，他說系統正在維護。他要我十五分鐘內，把金融卡正反面的照片和簡訊驗證碼傳給他。', '[{"tag": "authority", "text": "自稱租賃管理中心客服，說會凍結銀行帳戶"}, {"tag": "time_pressure", "text": "要十五分鐘內傳金融卡照片和驗證碼"}]'::jsonb, 1, '{31}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'fake-sale-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-11', 'fake-sale', true, '二手推車的運送訂金', '我在親子社團看上一台二手露營推車，總價約三千元，賣家傳來折疊裝箱的照片。他說週末的配送車下午就來收件，要先付約一千元訂金，接著傳來一個配色很像常用行動支付的付款頁，要我填姓名、電話再轉帳。我問能不能在平台建訂單，他說不用，這樣比較快，訂金沒入帳就改賣下一位。我正停在填姓名和電話的那個畫面，還沒送出。', '[{"tag": "authority", "text": "付款頁配色很像常用的行動支付"}, {"tag": "time_pressure", "text": "說訂金沒入帳就改賣下一位"}]'::jsonb, 2, '{32}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已移除帳號與連結', NULL, 'published', 'exam_message', 'fake-sale-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-06', 'fake-sale', true, '直播裡的絕版積木', '我在直播看到絕版積木套組，留言區接連有人喊編號，也有帳號貼出之前收到的照片。主播說這是整批清庫優惠，只剩最後三組，要拿到直播價就得加他的私人帳號，這一輪結束就不保留。加了之後，他要我先把全額匯到親友的帳戶，備註不要寫商品名稱，付款後才給寄件資料。他說寄出後會傳出貨照片和寄件單給我，我正在看那個帳號。', '[{"tag": "social_proof", "text": "留言區接連有人喊編號、貼收貨照"}, {"tag": "greed", "text": "說加私人帳號才拿得到直播價"}, {"tag": "time_pressure", "text": "說這一輪結束就不保留"}]'::jsonb, 2, '{29,68}'::bigint[], '改編自：165 全民防騙網「網路購物遇到詐騙了？社群買賣詐騙手法詳解」與數位發展部網路詐騙通報查詢網', NULL, 'published', 'exam_tactics', 'fake-sale-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-08', 'fake-sale', true, '限量外套的轉售貼文', '我在拍賣社團看到一件限量外套，價格比轉售行情少了大約三成。他改加通訊軟體私下跟我聊，我問能不能走平台，他說平台抽成太高，這個價格做不到。他說不能面交，要我五分鐘內先把約一萬五千元匯到他家人的帳戶，入帳後才給寄件單號，不然就不等了。我正在看他家人的帳戶名字，手機已經打開了網路銀行，手指就停在轉帳鍵上。', '[{"tag": "greed", "text": "價格比轉售行情少約三成"}, {"tag": "time_pressure", "text": "要你五分鐘內匯款，不然不等"}]'::jsonb, 2, '{30,68}'::bigint[], '改編自：165 全民防騙網「網路購物遇到詐騙了？社群買賣詐騙手法詳解」與數位發展部網路詐騙通報查詢網', NULL, 'published', 'exam_tactics', 'fake-sale-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-05', 'fake-sale', true, '陶藝團購的收款驗證', '我在手作市集平台接到一筆陶藝擺件的團購，買家很快傳來付款截圖，說錢已經付了，訂單要先交平台的結算人員確認。他傳來一個配色和平台很像的客服頁面，頁面要我先匯約二萬元驗證收款帳戶，說驗證完會連同貨款一起退回，半小時內沒完成，訂單就會取消。我打開平台的 App，卻看不到這筆訂單的付款紀錄，買家還在一直傳訊息催我。', '[{"tag": "authority", "text": "客服頁面配色和平台很像"}, {"tag": "time_pressure", "text": "說半小時內沒完成訂單就取消"}]'::jsonb, 3, '{31,39}'::bigint[], '改編自：165 全民防騙網「網路購物遇到詐騙了？社群買賣詐騙手法詳解」與數位發展部網路詐騙通報查詢網', NULL, 'published', 'exam_scenario', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-scam-12', 'fake-sale', true, '灌溉器材的撥款通知', '我透過農園設備的二手平台賣出一套灌溉器材，買家傳來一張公司採購的結案通知，上面列了品項、金額和收貨窗口，說結算代辦會聯絡我。代辦說我的帳戶還不能收款，得先轉約八千元進去跑一次流水，系統確認以後，貨款和這筆錢會一起撥給我。我打開平台的 App，怎麼找都找不到這筆訂單。他說今天不處理，買家就會向平台求償。', '[{"tag": "authority", "text": "結算代辦說帳戶還不能收款，要先跑流水"}, {"tag": "time_pressure", "text": "說今天不處理，買家就會求償"}]'::jsonb, 3, '{31,39}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_scenario', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-02', 'romance', true, '研究站測量員的同住計畫', '我在登山社群認識一位外派研究站的測量員，半年來我們常互傳登山路線和生活照。他說想回台灣跟我一起住，可是研究站的返國程序要先做配偶財力審核，需要一筆保證金存進指定帳戶，審核完就會退回。他說保證金存進去只是證明，一毛都不會動。我說想先視訊看看他，他說研究站的網路只准傳文字，沒辦法開鏡頭。我看著他傳來的帳戶資料。', '[{"tag": "trust_building", "text": "半年來常互傳路線和生活照，說想一起住"}, {"tag": "authority", "text": "說返國程序要做財力審核，要存保證金"}]'::jsonb, 2, '{72}'::bigint[], '改編自：165 打詐儀錶板「假交友（徵婚詐財）詐騙」常見手法清單', NULL, 'published', 'exam_message', 'romance-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-03', 'romance', true, '外派工程師的交易心得', '聊了三個月的他是外派的科技業工程師，每天噓寒問暖，常分享他的生活。他說自己跟著幾個大戶的節奏做海外外匯交易，已經不太需要為錢煩惱，還說在那個平台有內部管道，知道什麼時候會拉盤。我照他教的放了約四萬元，帳面兩週漲了快三成。他說這是他給我的見面禮。今天我想領出來，平台說要先繳一筆境外查核手續費，不能從帳面扣。', '[{"tag": "trust_building", "text": "聊了三個月，每天噓寒問暖"}, {"tag": "greed", "text": "說跟著大戶做外匯，已經不必為錢煩惱"}, {"tag": "authority", "text": "說在平台有內部管道，知道何時拉盤"}]'::jsonb, 2, '{69}'::bigint[], '改編自：165 打詐儀錶板「假交友（投資詐財）詐騙」常見手法清單', NULL, 'published', 'exam_message', 'romance-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-04', 'romance', true, '海外專案的結算款', '在攝影同好社群認識一個多月的他，很快說想跟我在一起，每天噓寒問暖。他說自己在海外做專案，有一筆結算款要匯回台灣，但他的帳戶在國外不能收，想借我的帳戶代收，等錢到了再轉給他，還會給我約三千元當謝禮。他要我先到提款機輸入一組代碼，開通外幣的收款功能，說錢到了想約我吃飯慶祝。我拿著提款卡出門，找最近的提款機。', '[{"tag": "trust_building", "text": "認識不久就說想在一起，每天噓寒問暖"}, {"tag": "greed", "text": "說代收後會給你約三千元謝禮"}]'::jsonb, 3, '{72}'::bigint[], '改編自：165 打詐儀錶板「假交友（徵婚詐財）詐騙」常見手法清單（借用帳戶與代收轉付）', NULL, 'published', 'exam_message', 'romance-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-05', 'romance', true, '出差時寄來的鋼筆', '交往兩個月的他這週去外地出差受訓，說買了一支高價鋼筆當紀念禮物，先寄給我。隔天有一個自稱物流承辦人的人傳訊息，說內容物估價比較高，要先付約兩萬五千元的查驗和保管費才能配送，倉庫下班前沒收到錢就退件。我問他能不能自己付，他說人在受訓，不能用手機轉帳，晚上會把錢還我。我看著承辦人給的帳號，戶名是一個人的名字。', '[{"tag": "authority", "text": "自稱物流承辦人要收查驗與保管費"}, {"tag": "time_pressure", "text": "說倉庫下班前沒收到款項就退件"}]'::jsonb, 2, '{72}'::bigint[], '改編自：165 打詐儀錶板「網友想見的不是你 是你荷包的錢」與Cofacts 真的假的民眾回報訊息原文，已去識別化', NULL, 'published', 'exam_message', 'romance-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-07', 'romance', true, '雙人陶藝課的預約', '語言交流社群的網友約我一起上雙人陶藝體驗課，我們視訊練習過幾次，他也傳了作品照片。他說那間工作室只接介紹，要我加課務主任的帳號預約。我問能不能直接上工作室的網站訂，他說網站不接這種體驗課。課務主任說要先買約一萬五千元的遊戲點數當訂金，把序號拍照傳給他，上課時可以抵學費。他說今晚沒完成，就取消這個時段。我正在查附近超商的位置。', '[{"tag": "authority", "text": "自稱課務主任，要點數序號當訂金"}, {"tag": "time_pressure", "text": "說今晚沒完成就取消時段"}]'::jsonb, 3, '{72}'::bigint[], '改編自：165 打詐儀錶板「網友想見的不是你 是你荷包的錢」與團隊整理的正規流程說明「正常網路交友互動特徵」', NULL, 'published', 'exam_message', 'romance-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-08', 'romance', true, '他家人住院的押金', '交往一陣子的他突然傳訊息，說住在高雄的家人急診住院，要先繳約四萬元的檢查押金，他的錢一時領不出來。我問是哪家醫院，他說太緊張忘了，晚點再跟我說。他傳來一張繳費單的照片，姓名和醫院標誌都被裁掉。他說一位醫院的財務人員願意幫忙保留檢查時段，但探視時間快結束了，請我先匯到那位財務人員的個人帳戶，下週發薪就還我。', '[{"tag": "authority", "text": "自稱醫院財務人員，說能保留時段並收款"}, {"tag": "time_pressure", "text": "說探視時間快結束，要你先匯款"}]'::jsonb, 2, '{72}'::bigint[], '改編自：Cofacts 真的假的民眾回報訊息原文與團隊整理的「正常網路交友互動特徵」，已移除姓名及院所資訊', NULL, 'published', 'exam_message', 'romance-08', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-09', 'romance', true, '舅舅籌的巡迴音樂劇', '交往半年的她說舅舅正在籌辦巡迴音樂劇，邀我加入製作的討論群，還傳了幾張排練照，說舞台已經在搭了。舅舅說巡演結束後，能拿回投入金額的好幾倍。她說今晚名單送出前，要把約六萬元匯到舅舅的個人帳戶認購，名額是特別替我們保留的。我問能不能先看合約，她說舅舅很忙，之後再補給我。我看著舅舅在群組裡傳來的個人帳號。', '[{"tag": "greed", "text": "說巡演後能拿回投入的好幾倍"}, {"tag": "time_pressure", "text": "說今晚名單送出前要匯款"}]'::jsonb, 3, '{69}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'romance-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-11', 'romance', true, '遠距交往中的進修資助', '攝影論壇認識的遠距伴侶在海外拍婚禮，我們聊過我想轉職的事。她說願意給我約二十萬元去進修，請一位跨境教育補助的代辦幫忙撥款。她說代辦是朋友介紹的，處理過很多次。代辦說要我把提款卡寄過去做帳戶測試，再把密碼傳給他，卡片今天寄出才排得進這週的作業，測完卡片會跟撥款通知一起寄回。我拿著提款卡，站在超商的門口。', '[{"tag": "greed", "text": "說願意給我約二十萬元去進修"}, {"tag": "time_pressure", "text": "說卡片今天寄出才排得進這週作業"}]'::jsonb, 1, '{72}'::bigint[], '改編自：司法院裁判書詐欺案件事實，已去識別化', NULL, 'published', 'exam_message', 'romance-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-10', 'romance', true, '表哥手上的限量郵票', '剛認識不久的網友先安慰我最近工作不順，我們聊得很投機。幾天後她說在海外工作的表哥很熟收藏市場，有一批限量紀念郵票，轉手預計能漲五倍，共同聊天群裡已經有朋友跟著買。她說表哥今天只能幫我保留兩套，要先把約四萬元匯到代辦人的帳戶，不用等見面再說。她說等漲了再請我吃飯，到時候順便見面。我正在看代辦人的帳號。', '[{"tag": "trust_building", "text": "先安慰你工作不順，聊得很投機"}, {"tag": "greed", "text": "說紀念郵票轉手預計能漲五倍"}, {"tag": "social_proof", "text": "說聊天群裡已經有朋友跟著買"}, {"tag": "time_pressure", "text": "說今天只能保留，要先匯款"}]'::jsonb, 2, '{69}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_tactics', 'romance-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-12', 'romance', true, '網友帳戶的解鎖協助', '語言交流社群認識的他說，自己在台灣的帳戶被凍結了，帳戶裡有他要來台灣的生活費。一名自稱銀行協作人員的人加入對話，說只要我把金融卡和密碼寄給他，用我的帳戶協助解鎖，之後就會把卡還我。協作人員說解鎖申請隔天下午就到期，要我今天就寄出。我低頭看著手上那張金融卡，寄件袋就放在旁邊的桌上，收件地址已經寫好了。', '[{"tag": "authority", "text": "自稱銀行協作人員加入對話"}, {"tag": "time_pressure", "text": "說解鎖申請隔天下午就到期"}]'::jsonb, 3, '{72}'::bigint[], '改編自：司法院裁判書詐欺案件事實，已去識別化', NULL, 'published', 'exam_tactics', 'romance-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-01', 'romance', true, '出差寄回的生日禮物', '交友軟體上聊了兩個多月的他在東南亞出差，說幫我準備了生日禮物，是一台高價相機和幾件收藏品，還夾了一筆現金。今天我收到一則物流通知，署名是一個國際組織合作的物流部門，說包裹要先繳約三萬元的進口稅和消費稅，海關暫存期限只到今天下班，逾期就退運。他說包裹裡的現金就夠還我了。他說他的卡在國外不能用，請我先幫忙付。', '[{"tag": "greed", "text": "說禮物有高價相機、收藏品，還夾了現金"}, {"tag": "authority", "text": "通知署名是國際組織合作的物流部門"}, {"tag": "time_pressure", "text": "說海關暫存只到今天下班，逾期退運"}]'::jsonb, 2, '{72}'::bigint[], '改編自：165 打詐儀錶板「假交友（徵婚詐財）詐騙」常見手法清單（寄件與清關稅費）', NULL, 'published', 'exam_scenario', 'romance-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-scam-06', 'romance', true, '一起存的搬家基金', '交往的他常和我談以後一起生活。我們說好一起存租屋搬家基金，他介紹一個境外平台，說他自己用了很久。我先存了約一萬元，試著提領一小筆也成功了。這週他說搬家前有一波行情，他願意替我出一半，但我得在晚上前補約八萬元。我說想先問問持牌的業者，他說兩個人的計畫不用問外人。他傳來客服的收款帳戶，戶名和上次不一樣。', '[{"tag": "greed", "text": "說行情難得，他願意替你出一半"}, {"tag": "time_pressure", "text": "要你晚上前補約八萬元"}]'::jsonb, 3, '{69}'::bigint[], '改編自：165 打詐儀錶板「網友想見的不是你 是你荷包的錢」與165 全民防騙網假投資通報', NULL, 'published', 'exam_scenario', 'romance-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-01', 'atm', true, '床單訂單的帳戶通知', '上午我接到一通電話，對方說是我前天買床單那家購物網站的客服，能說出我的名字和訂單金額。他說網站被駭客入侵，我的帳戶資料外洩，中午前就可能被盜領，已經幫我轉給合作銀行的專員。專員要我到附近銀行自助區的 ATM，照他在電話裡的指示輸入一組數字，完成帳戶安全重設。他說這樣盜領的人就動不了我的錢。我拿著提款卡走進自助區。', '[{"tag": "authority", "text": "自稱購物網站客服，再轉給合作銀行的專員"}, {"tag": "time_pressure", "text": "說中午前帳戶就可能被盜領"}]'::jsonb, 2, '{39}'::bigint[], '改編自：刑事警察局宣導『高風險業者提醒：駭客入侵、資料外洩話術（ATM）』', NULL, 'published', 'exam_message', 'atm-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-02', 'atm', true, '二手投影機的收款問題', '我在拍賣平台賣一台二手投影機，買家很快說已經付款，還傳來轉帳畫面的截圖。接著有人加我好友，自稱平台的金流專員，說我的帳號首次收款功能還沒開啟，貨款暫時撥不進來。他說只要打開行動銀行，照他給的步驟輸入一組代碼就能開通收款，不然買家的錢會被退回。買家也傳訊息催我，說他很急著要用。我打開行動銀行的轉帳頁。', '[{"tag": "trust_building", "text": "買家先傳轉帳截圖，讓你相信已付款"}, {"tag": "authority", "text": "自稱平台金流專員加你好友"}, {"tag": "time_pressure", "text": "說不照做買家的錢就會被退回"}]'::jsonb, 3, '{39}'::bigint[], '改編自：刑事警察局宣導『拍賣賣家遭詐：假買家假客服誘導 ATM 操作』', NULL, 'published', 'exam_message', 'atm-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-03', 'atm', true, '運動鞋訂單的續購設定', '傍晚有人打來，說是我買運動鞋那家網站的客服，開口就報出我的姓名、上個月買的鞋款和金額。他說系統把我誤設成自動續購方案，今晚就會扣第一筆，等一下銀行專員會打給我協助取消。不久專員來電，要我到 ATM，說會在電話裡引導我輸入一組解除代碼，取消後錢就不會被扣。他說整個過程大概五分鐘。我正走向便利商店的 ATM。', '[{"tag": "authority", "text": "報出姓名與訂單，再由銀行專員接手"}, {"tag": "time_pressure", "text": "說今晚就會扣第一筆"}]'::jsonb, 2, '{39}'::bigint[], '改編自：刑事警察局宣導『高風險業者提醒：誤設會員等級、解除分期付款詐騙（ATM）』', NULL, 'published', 'exam_message', 'atm-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-04', 'atm', true, '分行櫃台的匯款單', '我在分行櫃台填一張約十二萬元的匯款單，行員問我受款人是誰、為什麼要匯這筆錢。我照電話裡的人教的，說是匯給朋友的借款。其實是上週買冷氣的購物網站客服打來，說系統把我設成每月重複扣款，要匯一筆錢才能取消，沒處理完的這段時間還是會被扣。他交代行員不懂這個流程，不要提到這通電話，現在耳機裡他還在通話中，一直提醒我照說。', '[{"tag": "authority", "text": "自稱購物網站客服，教你對行員說是借款"}, {"tag": "time_pressure", "text": "說沒處理完的這段時間還是會被扣款"}]'::jsonb, 3, '{39}'::bigint[], '改編自：刑事警察局宣導『解除分期付款詐騙：重複扣款話術與規避行員關懷（ATM）』', NULL, 'published', 'exam_message', 'atm-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-06', 'atm', true, '海外電商的刷卡照會', '晚上我接到電話，對方自稱銀行風控人員，說得出我的姓名和最近刷卡的月份。他說我的卡被綁在一個海外線上商城，正在連續刷款，要我點他傳的止付連結，輸入卡號、有效期限和背面三碼，再把手機收到的驗證碼告訴他，才能把卡鎖起來。他的語氣很急，說掛斷後案件就要重新排隊，款項可能先被請走。我看著手機跳出的驗證碼簡訊，還沒念出來。', '[{"tag": "authority", "text": "自稱銀行風控人員，要你輸入卡號和驗證碼"}, {"tag": "time_pressure", "text": "說掛斷要重新排隊，款項會先被請走"}]'::jsonb, 2, '{39}'::bigint[], '改編自：金管會新聞稿「提醒民眾防範信用卡遭詐騙盜刷」', NULL, 'published', 'exam_message', 'atm-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-08', 'atm', true, '家具尾款的戶名核對', '我用行動銀行付家具配送尾款，轉帳前畫面顯示的受款戶名，和契約上的公司名稱有幾個字不同。不久我在通訊軟體收到自稱銀行客服的訊息，說這是跨行戶名重驗，要我改輸入他給的清算帳號，再匯一次約四萬元，系統送出後會自動取消。他說十分鐘內沒完成，我的帳戶會被列入異常。訊息裡還附了一張印著銀行標誌的說明圖。我把他給的帳號貼進轉帳頁。', '[{"tag": "authority", "text": "在通訊軟體自稱銀行客服"}, {"tag": "time_pressure", "text": "說十分鐘內沒完成帳戶會被列入異常"}, {"tag": "authority", "text": "要你改匯到他給的清算帳號"}]'::jsonb, 3, '{39}'::bigint[], '改編自：金管會新聞稿「金管會提醒民眾轉帳時核對受款人戶名，並注意防範詐騙」', NULL, 'published', 'exam_message', 'atm-08', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-09', 'atm', true, '門號的停用通知', '我收到一則簡訊，說我的門號被人在外地申辦了附加服務，一小時內沒處理就會停話，簡訊最後附了一個客服的帳號。我加了之後，自稱承辦人的人說我的銀行帳戶也可能被凍結，說這是電信和銀行一起處理的案子，要我到 ATM 把存款轉到指定的安全帳戶做資金清查，全程不要掛電話。他說清查完，錢會原封不動轉回來。我站在提款機前，他還在電話裡等我插卡。', '[{"tag": "authority", "text": "自稱電信承辦人，說銀行帳戶也會被凍結"}, {"tag": "time_pressure", "text": "說一小時內沒處理就會停話"}]'::jsonb, 1, '{39}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已移除帳號與連結', NULL, 'published', 'exam_message', 'atm-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-11', 'atm', true, '教育基金會的獎助金', '我申請了一個民間教育基金會的獎助金，承辦人傳來核定通知，說可以領約六萬元，通知上有基金會的名稱和章，看起來很正式。要撥款時，他說我的帳戶還沒通過認證，要先繳約三千元的認證費到他給的個人帳戶，認證完會連同獎助金一起撥給我。他說這一批撥款一小時後就截止，錯過就要等到下一期。我打開網路銀行，正在輸入他給的帳號，戶名是一個人的名字。', '[{"tag": "authority", "text": "承辦人傳來基金會的核定通知"}, {"tag": "time_pressure", "text": "說撥款批次一小時後就截止"}]'::jsonb, 1, '{39}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_message', 'atm-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-07', 'atm', true, '家具訂單的退款手續', '網購一張沙發後，有人打來自稱平台的退款專員，報得出我的訂單內容，還傳來一張退款申請表。他說系統設定錯誤，要我到銀行的臨櫃匯一筆錢，才能把多扣的款項退回，下午清算前一定要辦好。他交代我，行員問起就說是借給親戚的錢，千萬不要提到這通電話。我拿著號碼牌坐在銀行大廳，正照著申請表上的帳號，一格一格填匯款單。', '[{"tag": "authority", "text": "自稱退款專員，報出訂單並傳退款申請表"}, {"tag": "time_pressure", "text": "說下午清算前一定要辦好"}]'::jsonb, 3, '{39}'::bigint[], '改編自：金管會新聞稿「卓院長視察銀行業臨櫃關懷客戶阻詐執行情形」與刑事警察局解除分期宣導', NULL, 'published', 'exam_tactics', 'atm-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-12', 'atm', true, '海外押金的匯款審查', '我剛把海外租屋押金匯出，就收到一封很像是銀行寄來的郵件，說收款資料要通過反洗錢審查，請我聯繫中央銀行外匯部的專員。專員說兩小時內要再匯約四萬元保證款到他給的帳戶，審查結束後會一起退回。他還說這是保密程序，不能打給銀行，也不能跟家人或是朋友說。我看著郵件裡的收款帳號，手機已經打開了網路銀行的轉帳頁面。', '[{"tag": "authority", "text": "自稱中央銀行外匯部專員"}, {"tag": "time_pressure", "text": "要你兩小時內再匯保證款"}]'::jsonb, 3, '{39}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已移除帳號與連結', NULL, 'published', 'exam_tactics', 'atm-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-05', 'atm', true, '攝影方案的分期設定', '我預訂了一套婚禮攝影方案，晚上有自稱攝影平台客服的人打來，報得出方案和大約的價格，說付款被重複設成分六期，接著把電話轉給自稱銀行帳務人員的人。帳務人員說今晚就要截止，電話不能掛，要我到 ATM 插卡，照他念的輸入帳號和金額，說螢幕上的轉帳畫面只是回沖測試，錢等一下就會退回。我找到最近的一台提款機，插進了卡。', '[{"tag": "authority", "text": "把電話轉給自稱銀行帳務人員的人"}, {"tag": "time_pressure", "text": "說今晚就要截止，電話不能掛"}]'::jsonb, 1, '{39}'::bigint[], '改編自：金管會新聞稿「提醒民眾防範信用卡遭詐騙盜刷」與刑事警察局高風險業者解除分期宣導', NULL, 'published', 'exam_scenario', 'atm-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-scam-10', 'atm', true, '停車年費的扣款照會', '我收到一則訊息，說我的車牌被誤綁了停車服務的年度方案，信用卡會被扣款。對方自稱停車服務的支付客服，傳來一張有照片的識別證。他說如果我掛斷，今晚就會連續扣六期，要我打開網路銀行新增一個驗證帳戶，輸入約四萬元當取消代碼，再開分享畫面讓他確認。他提醒我不要跟銀行說，免得取消失敗。我打開信用卡的帳單，還沒看到這筆扣款。', '[{"tag": "authority", "text": "自稱停車服務支付客服，傳來識別證"}, {"tag": "time_pressure", "text": "說掛斷的話今晚會連續扣六期"}]'::jsonb, 2, '{39}'::bigint[], '改編自：Cofacts真的假的民眾回報之詐騙訊息原文，已去識別化', NULL, 'published', 'exam_scenario', 'atm-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-01', 'investment', false, '業務職缺的到職說明', '我應徵展場設備業務，面試在一間裝潢新穎的辦公室。人資帶我認識業務部經理，他說公司制度完整，新人都有專人帶。談到薪資時，他說底薪約三萬二加業績獎金，試用期三個月，到職當天就加勞健保。他請我週五前交存摺封面和身分證的影本，用來設定薪轉和投保，勞動契約也讓我帶回家看，說有問題可以打給人資。我手上拿著那份契約。', '[{"tag": null, "text": "薪資寫明底薪加獎金，勞動契約讓我帶回家看"}, {"tag": null, "text": "請交存摺封面和身分證影本，用來設定薪轉和投保"}]'::jsonb, 2, '{}'::bigint[], '依據：勞動契約與薪資轉帳之一般到職程序，對照假求職轉投資手法', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-01'), 'published', 'exam_message', 'investment-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-02', 'investment', false, '線上課程後的帳戶出金', '我上完一堂免費的股市線上課程，助教說可以用優惠方式買海外股票組合，要我在原本開戶的證券商用複委託下單。三週來帳面漲了一些，我在證券商的 App 按下賣出。成交明細列出手續費和當地規費，扣掉後的淨額會在幾個營業日後撥進我自己的交割帳戶。助教在課程群組提醒，這週五前賣出的款項下週三才會入帳。我正在核對那筆成交明細。', '[{"tag": null, "text": "賣出款扣除手續費後撥進自己的交割帳戶"}, {"tag": null, "text": "費用列在證券商 App 的成交明細，可以自己核對"}]'::jsonb, 3, '{}'::bigint[], '依據：證券商複委託交易之交割與費用揭露流程', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-02'), 'published', 'exam_message', 'investment-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-04', 'investment', false, '聊了兩個月的投資話題', '交友軟體上認識的他說自己是外派中東的工程人員，兩個月來每天傳訊息問我吃飯了沒，每週日晚上固定視訊半小時。他說自己每個月用薪水買一點海外債券基金，配息不高，但比放活存好一些。我問能不能跟著買，他把基金名稱傳給我，說風險要自己看。我在往來銀行的 App 搜到這一檔，商品頁列了費用、風險等級和可能虧損，錢從我自己的帳戶扣。', '[{"tag": null, "text": "只給基金名稱，讓我在自己往來銀行的 App 查"}, {"tag": null, "text": "銀行商品頁列出費用與風險，款項從本人帳戶扣"}]'::jsonb, 2, '{}'::bigint[], '依據：銀行基金銷售之風險揭露與自行下單流程，對照假交友投資詐騙', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-04'), 'published', 'exam_message', 'investment-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-05', 'investment', false, '電子股的新股申購', '我在理財論壇看到一則新股申購的分享，說最近有一檔電子零組件公司的新股公開申購，討論串很多人在比中籤率。我打開自己證券商的 App，在申購專區找到這一檔，頁面寫著承銷價、申購截止日是後天。扣款日前要把申購款和手續費存進我自己的交割帳戶，沒中籤會退回申購款。申購前要先勾選已閱讀公開說明書。我正在確認帳戶餘額夠不夠。', '[{"tag": null, "text": "在自己證券商的 App 申購專區辦理"}, {"tag": null, "text": "申購款從自己的交割帳戶預扣，沒中籤退回"}]'::jsonb, 2, '{1054}'::bigint[], '依據：團隊整理的正規流程說明「合法投資開戶與交易正規流程」', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-05'), 'published', 'exam_message', 'investment-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-07', 'investment', false, '自動交易服務的升級', '理財社團有人轉傳一支自動交易服務的說明影片，是一家銀行的機器人理財。我用原本的銀行 App 開通，放了約兩萬元進去。幾天後資產小幅增加，我也試著贖回一小筆，三個工作天就回到我的帳戶。今天 App 通知說，今晚前加碼到約十萬元以上，管理費可以打八折，錢從我自己的帳戶扣，要先重做一次風險問卷。我正在填問卷。', '[{"tag": null, "text": "開通、加碼、贖回都在自己的銀行 App 裡完成"}, {"tag": null, "text": "加碼前要先做風險問卷，款項從自己的帳戶扣"}]'::jsonb, 3, '{1054}'::bigint[], '依據：團隊整理的正規流程說明「合法投資開戶與交易正規流程」與金融商品揭露規範', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-07'), 'published', 'exam_message', 'investment-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-09', 'investment', false, '盤前的兩檔觀察名單', '我在通勤廣播聽到一段節目，介紹下一季的產業觀察清單，最後說完整的季報放在各家證券商的研究專區。我打開自己開戶的證券商 App，在研究專區找到這份季報，每一檔除了說為什麼看好，也寫了哪些情況會跌、資料是哪一天的。季報試閱到本週末，之後要訂閱，費用從我的交割帳戶扣，也可以不訂。我正在讀第二檔的風險說明。', '[{"tag": null, "text": "季報放在自己證券商 App 的研究專區"}, {"tag": null, "text": "每一檔都寫了看好的理由和會跌的情況"}]'::jsonb, 1, '{1054}'::bigint[], '依據：證券商研究報告之公開揭露與訂閱流程', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-09'), 'published', 'exam_message', 'investment-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-10', 'investment', false, '交易額度的啟用通知', '我在海外期貨交易服務的線上說明會填了試用申請，一位接待員幫我完成帳號設定。今天期貨商的 App 通知我，身分審查通過，交易功能已經開通。入金只能從我本人名下的銀行帳戶轉，今晚前完成第一次入金，可以減免一個月的手續費。我先查了期貨商的登記名冊，名字對得上，再從 App 打開入金頁，帳號欄位是我自己的銀行帳戶。', '[{"tag": null, "text": "審查結果在期貨商自己的 App 通知"}, {"tag": null, "text": "期貨商的登記查得到，入金只能從本人帳戶"}]'::jsonb, 2, '{1054}'::bigint[], '依據：期貨商開戶審查與本人帳戶入金之正規流程', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-10'), 'published', 'exam_message', 'investment-10', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-11', 'investment', false, '玻璃藝術品的收藏計畫', '我在工藝展後加入一個玻璃藝術品收藏群，有人分享一場作者簽名作品的拍賣。主辦的拍賣公司有商業登記，目錄寫了尺寸、保存狀況、作者和估價區間，也寫著收藏品不保證增值。這週末開放預展，可以到現場看作品，證書號碼也能自己拿去查。得標後錢付給拍賣公司，作品當場交給得標人。我正在查預展的時間和地點，想週末過去看。', '[{"tag": null, "text": "預展可以看作品，證書號碼能自己查"}, {"tag": null, "text": "得標款付給有商業登記的拍賣公司，當場取件"}]'::jsonb, 3, '{1055}'::bigint[], '依據：消保法交易資訊揭露原則與拍賣公司書面交易流程', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-11'), 'published', 'exam_message', 'investment-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-06', 'investment', false, '教育金講座後的方案說明', '我參加一場子女教育金規劃的線上講座，主講人說自己在證券公司服務多年，投影片放著證照照片。聊天室有不少家長分享定期投入的經驗。會後一位營業員私訊我，說有一檔教育金主題的基金這週募集截止，錯過也有其他商品可以選。他說要買的話在我原本的證券 App 下單，從我自己的帳戶扣款，買之前要先做風險屬性評估。我正在讀公開說明書的費用那一頁。', '[{"tag": null, "text": "在自己的證券 App 下單，從自己的帳戶扣款"}, {"tag": null, "text": "購買前要先做風險屬性評估，錯過募集也能選別的商品"}]'::jsonb, 3, '{1054}'::bigint[], '依據：團隊整理的正規流程說明「合法投資開戶與交易正規流程」與證券商風險及費用揭露義務', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-06'), 'published', 'exam_scenario', 'investment-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('investment-exam-legit-08', 'investment', false, '同事分享的海外債券', '以前的同事在群組分享一家物流業公司發行的海外債券，兩年到期，配息率比定存高一些，群裡有幾個人說自己也買過。我在往來銀行的 App 搜尋那檔債券，頁面列出發行公司、信用評等、到期日、配息率和違約風險，最低申購金額是一萬美元，款項從我自己的外幣帳戶扣。申購期到這週四，額滿就提早截止。我正在看信用評等那一欄。', '[{"tag": null, "text": "在自己往來銀行的 App 查到並申購"}, {"tag": null, "text": "款項從自己的外幣帳戶扣，頁面列出違約風險"}]'::jsonb, 2, '{1054}'::bigint[], '依據：銀行海外債券銷售之商品資訊揭露與申購流程', (SELECT id FROM game_cases WHERE case_key = 'investment-exam-scam-08'), 'published', 'exam_scenario', 'investment-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-02', 'shopping', false, '桌遊擴充盒的交易頁面', '我在桌遊同好社團徵求一盒限量擴充，有賣家私訊說手上剛好有，價格也合理。他說已經在大型二手平台上架，把商品名稱傳給我，請我自己到平台搜尋下單，可以選超商取貨付款。我在平台找到那個賣場，有一百多則交易評價，商品照片和他私訊給我的是同一盒。他說今天下單明天就能寄，晚一點下單也沒關係。我順便看了賣家的退貨說明。我把商品加進購物車。', '[{"tag": null, "text": "請你自己到二手平台搜尋賣場下單"}, {"tag": null, "text": "付款走平台的超商取貨付款"}]'::jsonb, 2, '{}'::bigint[], '依據：電商平台站內下單與取貨付款流程，對照假交易頁面連結的手法', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-02'), 'published', 'exam_message', 'shopping-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-03', 'shopping', false, '台中小兩房的租屋訂金', '轉職搬家前，我在租屋社團看到台中一間小兩房，租金比附近行情低一些，照片明亮，條件寫得很清楚。我私訊後，房東說他本人週六下午可以帶看。看完房，他說要租的話先付約一個月租金當訂金，這間就幫我留著，不會再約別人。他給我看身分證和房屋權狀，名字和地址都對得上，也拿出一張保留單，寫了訂金、保留到週五和沒簽約時怎麼退。我正在讀那張保留單。', '[{"tag": null, "text": "房東本人帶看，證件和權狀對得上"}, {"tag": null, "text": "保留單寫明訂金、期限和沒簽約時怎麼退"}]'::jsonb, 2, '{}'::bigint[], '依據：內政部住宅租賃契約書範本與一般租屋簽約流程', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-03'), 'published', 'exam_message', 'shopping-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-04', 'shopping', false, '搬家出清的平板電腦', '我在社群買賣社團看到一台平板電腦，賣家說搬家整理要出清，價格比行情便宜了快三成。我私訊問為什麼這麼便宜，他說螢幕有一道刮痕，電池健康度只剩七成，還拍了照片給我看。他住在台南，我在台北，他說可以在二手平台開一個賣場給我下單，用平台的付款保障，我收到確認沒問題，平台才撥款給他。我正在平台上看他開的賣場。', '[{"tag": null, "text": "低價有說明原因，主動拍出瑕疵"}, {"tag": null, "text": "在二手平台下單，收到確認後平台才撥款"}]'::jsonb, 1, '{}'::bigint[], '依據：二手平台款項代管與買家確認收貨後撥款之流程', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-04'), 'published', 'exam_message', 'shopping-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-06', 'shopping', false, '開學前的刺繡布包', '孩子快開學了，我在社群上看到一家工作室的客製刺繡姓名布包，作品照片很可愛。我私訊店家，他們傳來布料樣式和刺繡草圖，請我到官網的訂購表單下單。官網列了公司登記名稱、地址和電話，結帳頁寫著客製品排入製作後不能因為個人喜好退貨，付款可以刷卡。店家說開學前的排程快滿了，這週日前下單來得及。我正在填訂購表單。', '[{"tag": null, "text": "在官網訂購表單下單，網站列出登記名稱與地址"}, {"tag": null, "text": "客製品不退的條件寫在結帳頁，可以刷卡"}]'::jsonb, 3, '{1055}'::bigint[], '依據：消保法通訊交易客製商品之退貨例外與資訊揭露義務', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-06'), 'published', 'exam_message', 'shopping-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-09', 'shopping', false, '運動服包裹的稅費通知', '我上週在海外網站買了運動服，今天收到購物網站的物流通知，說包裹到了海關，要繳約兩百元的進口稅費。我打開購物網站的訂單頁，物流狀態寫著待繳稅費，連到我之前在報關 App 設好的實名委任資料。稅費可以在 App 裡刷卡繳，也能在送達時付給司機。訂單頁說七天內沒繳會退回寄件地。我正在報關 App 確認那筆稅費。', '[{"tag": null, "text": "稅費狀態在購物網站訂單頁查得到"}, {"tag": null, "text": "在自己設定的報關 App 繳費，或送達時付給司機"}]'::jsonb, 1, '{1055}'::bigint[], '依據：海關進口快遞貨物稅費之實名委任與線上繳納流程', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-09'), 'published', 'exam_message', 'shopping-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-10', 'shopping', false, '掃地機器人的訂單郵件', '我收到一封購物平台的訂單郵件，內容是一台約一萬兩千元的掃地機器人，寫著宅配到管理室。我不記得下過這筆單，打開原本的購物 App 查訂單紀錄，找到同一筆還沒出貨的訂單，付款方式是我綁定的信用卡。頁面寫著取消後會退回原卡，並留下取消紀錄，也可以打卡片背面的電話查授權。我先問家人是不是他們用我的帳號買的，還沒按取消。', '[{"tag": null, "text": "在原本的購物 App 查得到同一筆訂單"}, {"tag": null, "text": "取消後退回原卡，會留下取消紀錄"}]'::jsonb, 2, '{1055}'::bigint[], '依據：電商平台站內訂單查詢與付款方式紀錄', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-10'), 'published', 'exam_message', 'shopping-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-11', 'shopping', false, '上班族的膳食纖維方案', '我在廣告上看到給久坐上班族的膳食纖維粉，私訊後客服說這是食品，不能保證改善什麼症狀，腸胃有問題要先看醫生。她把官網的商品頁傳給我，上面列了成分、營養標示、食品業者登錄字號和不適用的人。這週買三個月份打八折，約八千元，可以刷卡或貨到付款，收到沒拆封七天內可以退。她說不急，想清楚再買就好。我正在看營養標示那一欄。', '[{"tag": null, "text": "官網列出成分、營養標示與食品業者登錄字號"}, {"tag": null, "text": "可刷卡或貨到付款，未拆封七天內可退"}]'::jsonb, 3, '{1055}'::bigint[], '依據：食品安全衛生管理法標示規定與消保法通訊交易規範', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-11'), 'published', 'exam_message', 'shopping-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-12', 'shopping', false, '會員抽獎的中獎通知', '我最近在購物平台參加會員抽獎，今天收到一則通知，說我抽中了約兩千元的購物金。我打開原本的購物 App，活動頁的中獎名單上真的有我，購物金已經放進我的帳戶，下一筆訂單就能折抵，使用期限是三個月。通知裡沒有連結，只寫了到 App 查詢的方式，也沒要我填銀行資料。我正在看購物金的使用規則，想著下次要買什麼。', '[{"tag": null, "text": "中獎名單在原本的購物 App 活動頁查得到"}, {"tag": null, "text": "購物金直接進帳戶，不用填銀行資料"}]'::jsonb, 2, '{1055}'::bigint[], '依據：購物平台會員活動之中獎公告與購物金發放方式', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-12'), 'published', 'exam_message', 'shopping-12', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-05', 'shopping', false, '換季促銷的空氣清淨機', '我在社群廣告點進一個大型購物平台，換季促銷的空氣清淨機只要市面價格的一半，還加送一組替換濾網，商品下面排滿五星評價，不少留言附了開箱照。我看了一下，是品牌的官方旗艦館，促銷到今晚十二點，庫存數字一直在減少。結帳頁可以刷卡、貨到付款或超商付款，也寫著七天鑑賞期。評價裡也有人抱怨運送比較慢。我正在比較型號的適用坪數。', '[{"tag": null, "text": "在大型購物平台的品牌旗艦館結帳"}, {"tag": null, "text": "可以刷卡、貨到付款或超商付款"}]'::jsonb, 2, '{1055}'::bigint[], '依據：電商平台促銷活動之一般結帳流程與消保法通訊交易規範', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-05'), 'published', 'exam_scenario', 'shopping-05', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('shopping-exam-legit-08', 'shopping', false, '溫泉旅宿的團購方案', '朋友轉傳一則宜蘭溫泉旅宿的團購貼文，寒假週末一晚含早餐，價格比平常便宜不少，留言區很多人在揪團。我私訊小編，他說優惠要從旅宿官網的訂房系統下單，輸入團購代碼就會折價，付款可以刷卡，入住前七天取消全額退。我在官網找到同一間旅宿，名稱、地址和電話跟貼文一樣，輸入代碼後價格也對。小編說代碼只到月底有效。我正在選入住日期。', '[{"tag": null, "text": "在旅宿官網的訂房系統用團購代碼下單"}, {"tag": null, "text": "官網的名稱、地址、電話與貼文一致"}]'::jsonb, 2, '{1055}'::bigint[], '依據：旅宿業官網訂房與取消規定之一般流程', (SELECT id FROM game_cases WHERE case_key = 'shopping-exam-scam-08'), 'published', 'exam_scenario', 'shopping-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-01', 'fake-sale', false, '直播間的二手機械錶', '我滑到一個二手機械手錶的直播，主播說這批是海外倉庫清算的貨，價格比一般二手錶行低不少，留言區不停有人刷搶標和曬單。我看上一支錶，主播說要在購物平台的直播頁按下單，用平台付款，七天內可以退，錶的序號和保固卡照片也放在商品頁。我問能不能便宜一點，他說直播價已經是最低了。我點進商品頁，比對直播畫面裡的錶和照片是不是同一支。', '[{"tag": null, "text": "在購物平台直播頁下單，用平台付款"}, {"tag": null, "text": "商品頁列出序號與保固卡照片，七天內可以退"}]'::jsonb, 2, '{}'::bigint[], '依據：電商平台直播購物之站內下單與通訊交易解除規定', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-01'), 'published', 'exam_message', 'fake-sale-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-10', 'fake-sale', false, '工作室結束營業的出清', '我在攝影器材社團看到一則工作室結束營業的出清，三腳架和攝影燈都只要幾百元，照片裡的器材都很新。我私訊賣家，她約我到原本的工作室看貨，地址和商業登記上的一樣，可以現場開燈測試，沒問題再付款，也會開品項收據。她還說有一支三腳架的腳有點鬆，會再算便宜一點。她說我看了不買也沒關係。我約了明天晚上七點過去，看那兩盞攝影燈。', '[{"tag": null, "text": "約到工作室現場測試後再付款"}, {"tag": null, "text": "工作室地址和商業登記一樣，會開收據"}]'::jsonb, 1, '{1056}'::bigint[], '依據：二手交易面交與當場驗貨的一般作法', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-10'), 'published', 'exam_message', 'fake-sale-10', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-02', 'fake-sale', false, '二手平板的寄件與收款', '我在拍賣平台賣一台二手平板，買家談得很順，下單時選了店到店寄件。我打開拍賣平台的 App，訂單頁顯示買家已付款，要我在三天內到超商寄件，寄件編號系統已經產生好了。訂單頁還提醒我，收款帳戶要在 App 的錢包設定綁定本人帳戶，買家取貨後才會撥款。買家傳訊息說謝謝，問我大概什麼時候寄。我把平板裝箱，準備明天到超商寄件。', '[{"tag": null, "text": "付款與寄件編號都在拍賣 App 的訂單頁"}, {"tag": null, "text": "收款帳戶在 App 錢包設定綁定，取貨後才撥款"}]'::jsonb, 2, '{}'::bigint[], '依據：拍賣平台款項代管與店到店寄件之站內流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-02'), 'published', 'exam_message', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-04', 'fake-sale', false, '限量掌上遊戲機的面交', '我在拍賣社團看到一台限量的掌上遊戲機，價格比市面便宜一點。賣家先答應面交，可是他說輪班時間一直改，前後改了兩次都沒約成。他提議改用二手平台下單，用平台的付款保障寄給我，運費他出，也願意先拍開機畫面和序號給我看。我收到他傳的照片，序號和盒子上的一樣。他說如果我不放心，也可以等他排到休假再面交。我正在平台上找他開的賣場。', '[{"tag": null, "text": "改用二手平台下單，用平台的付款保障"}, {"tag": null, "text": "先拍開機畫面與序號，和盒子上的一致"}]'::jsonb, 2, '{}'::bigint[], '依據：二手平台款項代管與買家確認收貨後撥款之流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-04'), 'published', 'exam_message', 'fake-sale-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-03', 'fake-sale', false, '短影音廣告的展示機出清', '我在短影音廣告看到高階咖啡機的展示機出清，價格比新品低不少。點進去是品牌的官方網站，活動頁有倒數計時，寫著展示機數量有限。頁面最下方列了公司名稱、統一編號、客服電話和門市地址，展示機有半年保固，結帳可以刷卡或貨到付款，也寫明退貨方式。我也查到品牌在台北有門市可以看實機。我正在比較兩台展示機的使用時數。', '[{"tag": null, "text": "網站列出公司名稱、統一編號、客服電話與門市"}, {"tag": null, "text": "可以刷卡或貨到付款，寫明保固與退貨方式"}]'::jsonb, 1, '{}'::bigint[], '依據：消保法通訊交易之企業經營者資訊揭露義務', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-03'), 'published', 'exam_message', 'fake-sale-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-07', 'fake-sale', false, '劇迷社團的舞台劇門票', '我在劇迷交流社團徵一張舞台劇門票，有人私訊說朋友臨時不能去，可以原價轉讓。他說這場的電子票可以在售票系統裡轉讓，等我把售票帳號給他，他從系統把票轉過來，我在自己的帳號看到票之後再付款就好。社團裡也有幾個人說跟他交易過。他說演出前一週都可以轉。我問付款方式，他說等票到了我再轉帳給他就好。我正在登入售票系統確認我的帳號。', '[{"tag": null, "text": "電子票從售票系統轉到你的帳號"}, {"tag": null, "text": "看到票進入自己的帳號後才付款"}]'::jsonb, 3, '{1056}'::bigint[], '依據：票務系統電子票轉讓之一般流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-07'), 'published', 'exam_message', 'fake-sale-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-09', 'fake-sale', false, '露營裝備出租的實名確認', '我在常用的租賃平台接了一筆露營裝備出租的單，客人付款後，我收到平台的通知，提醒出租人在明天中午前做一次身分確認。我自己打開 App，在帳戶設定裡看到同樣的提醒，要我拍身分證的兩面，再拍一張自拍比對，完成以後才能把裝備租出去。頁面寫著這個步驟只要做過一次就好。我正在 App 裡對著光，拍身分證的正面。', '[{"tag": null, "text": "自己打開 App，在帳戶設定看到同樣的提醒"}, {"tag": null, "text": "只要上傳身分證和自拍，做過一次就好"}]'::jsonb, 1, '{1056}'::bigint[], '依據：二手平台高價交易之身分確認與站內設定流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-09'), 'published', 'exam_message', 'fake-sale-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-11', 'fake-sale', false, '二手推車的運送訂金', '我在親子社團看上一台二手露營推車，總價約三千元，賣家傳來折疊裝箱的照片。他說週末的配送車下午就來收件，配送要先收約一千元訂金，請我到二手平台下單。我打開平台 App，看到他建的賣場和推車的實拍照片，賣場評價也不少，訂單頁寫著總價、訂金怎麼抵扣和運送方式，款項由平台保管，沒寄出會退款。我正在選要用信用卡還是超商付款。', '[{"tag": null, "text": "在二手平台下單，付款按鈕在平台內"}, {"tag": null, "text": "款項由平台保管，沒寄出會退款"}]'::jsonb, 2, '{1056}'::bigint[], '依據：二手平台訂金與運送安排之站內付款流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-11'), 'published', 'exam_message', 'fake-sale-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-05', 'fake-sale', false, '陶藝團購的收款驗證', '我在手作市集平台接到一筆陶藝擺件的團購，買家下單付款後，平台通知這筆款項會先由平台代管。站內客服提醒我，明晚前要補上整批的規格和包裝照片，沒補的話訂單會取消、錢退回買家。我從 App 的訂單頁上傳照片，頁面顯示審核中。買家傳訊息說不急，等我寄出就好。訂單頁也寫著寄出後的撥款時間。我正在拍擺件的包裝照片。', '[{"tag": null, "text": "款項由平台代管，補件在 App 訂單頁上傳"}, {"tag": null, "text": "沒補件只會取消訂單、退錢給買家"}]'::jsonb, 3, '{1056}'::bigint[], '依據：二手平台高價交易之款項代管與站內補件流程', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-05'), 'published', 'exam_scenario', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('fake-sale-exam-legit-12', 'fake-sale', false, '灌溉器材的撥款通知', '我透過農園設備的二手平台賣出一套灌溉器材，平台寄來一張公司採購的訂單，列了品項、金額和收貨窗口。我打開 App 的賣家後台，找到同一筆訂單，狀態是已付款、待出貨，寫著要分兩批配送。後台寫著貨款由平台代管，買家確認收貨後會撥到我綁定的帳戶。買家問能不能今天先寄第一批，我說明天，他說沒關係。我正在印第一批的寄件標籤。', '[{"tag": null, "text": "賣家後台找到同一筆已付款訂單"}, {"tag": null, "text": "貨款由平台代管，撥到我綁定的帳戶"}]'::jsonb, 3, '{1056}'::bigint[], '依據：正規電商交易流程與拍賣平台款項代管撥款機制', (SELECT id FROM game_cases WHERE case_key = 'fake-sale-exam-scam-12'), 'published', 'exam_scenario', 'fake-sale-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-02', 'romance', false, '研究站測量員的同住計畫', '我在登山社群認識一位外派研究站的測量員，半年來我們常互傳登山路線和生活照。他說任務結束想回台灣跟我一起住，也想先辦結婚登記，叫我自己打戶政事務所公布的電話，問要準備什麼。我打了，對方說文件清單在網站上，規費到現場再繳。他說回來後我們先見面，再一起去辦。我正在看網站上的文件清單，準備先把要帶的證件找出來。', '[{"tag": null, "text": "戶政公布的電話說明文件清單，規費到場繳"}, {"tag": null, "text": "結婚登記等他回來，兩人一起去辦"}]'::jsonb, 2, '{}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與戶政結婚登記流程', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-02'), 'published', 'exam_message', 'romance-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-03', 'romance', false, '外派工程師的交易心得', '聊了三個月的他是外派的科技業工程師，每天噓寒問暖，常分享他的生活。他說自己每個月會從薪水撥一部分，定期定額買全球型基金，兩年下來有賺也有賠過，還傳了對帳單給我看，有一年是虧的。我問他推薦哪一檔，他說每個人能承受的風險不一樣，叫我先到自己的銀行做風險評估，不要跟著他買。我們約好他下個月回台灣時見面吃飯。', '[{"tag": null, "text": "叫我先到自己的銀行做風險評估，不要跟著他買"}, {"tag": null, "text": "對帳單上有虧損的那一年，沒說穩賺"}]'::jsonb, 2, '{}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與「合法投資開戶與交易正規流程」', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-03'), 'published', 'exam_message', 'romance-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-04', 'romance', false, '海外專案的結算款', '在攝影同好社群認識一個多月的他，很快說想跟我在一起，每天噓寒問暖。他說自己在海外做專案，有一筆結算款要匯回台灣，他在台灣的銀行有開戶，已經打去問過收外幣要多少手續費。他問我能不能幫忙看銀行寄來的外幣收款說明，上面的受款人是他本人，手續費從入帳的錢裡扣。我正在看那份說明，還沒回他，想先問問我自己的銀行。', '[{"tag": null, "text": "銀行文件寫受款人是他本人，費用從入帳款扣"}, {"tag": null, "text": "他自己向往來銀行問收款手續費"}]'::jsonb, 3, '{}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」，對照借用帳戶代收轉付的交友詐騙', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-04'), 'published', 'exam_message', 'romance-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-05', 'romance', false, '出差時寄來的鋼筆', '交往兩個月的他這週去外地出差受訓，說買了一支鋼筆當紀念禮物，用宅配寄給我，把物流單號傳了過來。他說筆是在文具店買的，盒子裡有保固卡。今天物流的簡訊說包裹下午送到，簽收時要出示證件。我在物流公司的網站用單號查，寄件日和收件資料都對得上，頁面寫著運費已經由寄件人付了。我正在確認下午能不能到管理室簽收包裹。', '[{"tag": null, "text": "用同一個單號在物流網站查得到寄件資料"}, {"tag": null, "text": "運費已由寄件人付，簽收只要出示證件"}]'::jsonb, 2, '{1057}'::bigint[], '依據：團隊整理的正規流程說明「正常網路交友互動特徵」', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-05'), 'published', 'exam_message', 'romance-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-07', 'romance', false, '雙人陶藝課的預約', '語言交流社群的網友約我一起上雙人陶藝體驗課，我們視訊練習過幾次，他也傳了作品照片。他說那間工作室要先付每人約一千元的訂金，他已經在工作室的網站幫兩個人付好了，確認信上有預約編號，三天前取消可以全額退。我自己上網查到工作室的公開電話，打去核對確認信上的預約編號和訂金，店員說都對。我順便問了附近有沒有停車位。', '[{"tag": null, "text": "自己查工作室的公開電話，核對同一筆預約"}, {"tag": null, "text": "訂金在工作室網站付，三天前取消全額退"}]'::jsonb, 3, '{1057}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與餐飲訂位可核對業者、訂金及退款條件的正規流程', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-07'), 'published', 'exam_message', 'romance-07', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-08', 'romance', false, '他家人住院的押金', '交往一陣子的他突然傳訊息，說住在高雄的家人急診住院，要先繳一筆檢查押金。他問我能不能陪他去醫院確認費用，也請我先打醫院公開的總機，轉住院櫃檯問項目。我們到了醫院，櫃檯當面給了有病人資料的繳款單，櫃檯的人說刷卡或付現都可以，他準備用自己的卡付，收據會開在病人名下。他說家人的健保卡和身分證都帶來了。我正在跟他一起看那張單子上的項目。', '[{"tag": null, "text": "櫃檯當面給有病人資料的繳款單"}, {"tag": null, "text": "他用自己的卡付，收據開在病人名下"}]'::jsonb, 2, '{1057}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與醫療院所直接繳款並取得收據的可核對流程', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-08'), 'published', 'exam_message', 'romance-08', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-09', 'romance', false, '舅舅籌的巡迴音樂劇', '交往半年的她說舅舅正在籌辦巡迴音樂劇，在公開的募資平台做演出票預購。她把募資頁的名稱傳給我，頁面寫明這是預購，支持約五百元可以在節目冊列名，約一千五百元附首演票。募資到月底截止，付款走平台的金流，沒達標會退款，頁面也列了舅舅公司的名稱和過去的演出。她說我有興趣再支持，不用勉強。我正在讀募資頁的退款說明。', '[{"tag": null, "text": "募資頁寫明是預購，沒有承諾分潤"}, {"tag": null, "text": "付款走募資平台，沒達標會退款"}]'::jsonb, 3, '{1057,1055}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與消保法預購型群眾募資規範', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-09'), 'published', 'exam_message', 'romance-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-11', 'romance', false, '遠距交往中的進修資助', '攝影論壇認識的遠距伴侶在海外拍婚禮，我們聊過我想轉職的事。她說見面後如果我們都還有共識，可以借我一部分進修費，但要簽書面的借款契約，寫清楚利息和還款日，錢會從她的帳戶直接匯到我本人的帳戶。她下個月回台灣，我們約好先見面再談。她說借不借都不影響我們。她也說可以先陪我比較幾間學校的課程。我正在整理學費預算。', '[{"tag": null, "text": "借款要簽書面契約，寫清楚利息與還款日"}, {"tag": null, "text": "錢從她的帳戶直接匯到我本人的帳戶"}]'::jsonb, 1, '{1057}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與民法消費借貸書面契約原則', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-11'), 'published', 'exam_message', 'romance-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-01', 'romance', false, '出差寄回的生日禮物', '交友軟體上聊了兩個多月的他在東南亞出差，說幫我準備了生日禮物，用國際快遞寄回台灣。早上快遞傳來簡訊，提醒這件包裹有約三百元的進口稅要繳，可以上快遞公司的網站繳，或等包裹送來時交給司機。我自己打開快遞公司的官網，輸入他給的單號，畫面上的品名和稅額跟簡訊寫的一樣，收款的是快遞公司。我還沒按下付款的按鈕。', '[{"tag": null, "text": "自己在快遞官網用單號查到品名和稅額"}, {"tag": null, "text": "稅額付給快遞公司，也可以送達時付給司機"}]'::jsonb, 2, '{}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與國際快遞進口稅費之官網查詢及繳納流程', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-01'), 'published', 'exam_scenario', 'romance-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('romance-exam-legit-06', 'romance', false, '一起存的搬家基金', '交往的他常和我談以後一起生活。我們說好一起存租屋搬家基金，他提議各自在自己的銀行開一個存款帳戶，每個月各存約五千元，存到明年六月。他說錢放在自己名下比較清楚，要不要買基金也各自決定。週末我們一起去看了兩間套房，他把看房的筆記整理好傳給我，連租金和押金都記下來了。我正在銀行 App 設定每個月自動轉存。', '[{"tag": null, "text": "錢各自存在自己名下的銀行帳戶"}, {"tag": null, "text": "要不要投資各自決定，沒有指定平台"}]'::jsonb, 3, '{1057,1054}'::bigint[], '依據：團隊整理的「正常網路交友互動特徵」與「合法投資開戶與交易正規流程」', (SELECT id FROM game_cases WHERE case_key = 'romance-exam-scam-06'), 'published', 'exam_scenario', 'romance-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-01', 'atm', false, '床單訂單的帳戶通知', '上午我接到一通電話，對方說是我前天買床單那家購物網站的客服，能說出我的名字和訂單金額。他說訂單上的地址少了門牌號碼，物流沒辦法派送，請我登入 App 在訂單頁補上，中午前補好今天就能出貨。我問能不能在電話裡直接改，他說要我自己登入修改，才能確認是本人，也可以從 App 的客服頁留言。我打開 App 找那張訂單。', '[{"tag": null, "text": "請你自己登入 App 在訂單頁補地址"}, {"tag": null, "text": "可以改從 App 的客服頁聯絡，不必在電話裡操作"}]'::jsonb, 2, '{}'::bigint[], '依據：電商訂單配送資料補正之站內處理流程，對照解除分期詐騙的來電話術', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-01'), 'published', 'exam_message', 'atm-01', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-02', 'atm', false, '二手投影機的收款問題', '我在拍賣平台賣一台二手投影機，買家很快說已經付款，還傳來轉帳畫面的截圖。我打開拍賣平台的 App，訂單頁顯示買家已付款，款項由平台保管，旁邊跳出提醒：首次收款要先在錢包設定綁定本人帳戶。我照著在 App 裡填了自己的帳號，系統說核對要一到兩個工作天，出貨後買家確認收貨就撥款。買家說不急，等我有空再寄。我正在印寄件單。', '[{"tag": null, "text": "付款狀態在拍賣平台 App 的訂單頁確認"}, {"tag": null, "text": "首次收款只要在錢包設定綁定本人帳戶"}]'::jsonb, 3, '{}'::bigint[], '依據：拍賣平台款項代管與賣家收款帳戶設定流程', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-02'), 'published', 'exam_message', 'atm-02', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-03', 'atm', false, '運動鞋訂單的續購設定', '傍晚有人打來，說是我買運動鞋那家網站的客服，開口就報出我的姓名、上個月買的鞋款和金額。他說那批鞋有鞋底脫膠的瑕疵，正在召回，問我要不要換一雙新的。換貨要在 App 的訂單頁申請，物流會到府收件，運費由他們負擔，下週五前申請都可以。他說召回公告也放在 App 首頁。舊鞋等物流來收件時交給司機就好。我打開 App 找那筆訂單。', '[{"tag": null, "text": "換貨在 App 的訂單頁申請，物流到府收件"}, {"tag": null, "text": "召回公告可以在 App 首頁自己查到"}]'::jsonb, 2, '{}'::bigint[], '依據：商品瑕疵召回與電商站內換貨流程，對照解除分期詐騙的來電話術', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-03'), 'published', 'exam_message', 'atm-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-04', 'atm', false, '分行櫃台的匯款單', '我在分行櫃台填一張約十二萬元的匯款單，行員問我受款人是誰、為什麼要匯這筆錢，還問有沒有人打電話叫我來。我說是匯給裝修公司的第二期工程款，拿出和他們簽的工程契約和請款單。行員核對契約上的公司名稱和帳戶戶名一致，請我在關懷提問單上簽名。她也問這家公司是怎麼找到的、有沒有去過工地。我有點不耐煩，但還是一題一題回答。', '[{"tag": null, "text": "匯款用途有工程契約與請款單可以核對"}, {"tag": null, "text": "受款戶名與契約上的公司名稱一致"}]'::jsonb, 3, '{}'::bigint[], '依據：中華民國銀行公會「臨櫃作業關懷客戶提問參考範本」與金管會防制金融詐騙宣導', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-04'), 'published', 'exam_message', 'atm-04', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-06', 'atm', false, '海外電商的刷卡照會', '晚上我接到電話，對方自稱銀行風控人員，說得出我的姓名和最近刷卡的月份。他說我的卡在一個海外線上商城有一筆刷卡，想確認是不是本人。我說不是，他說會先把卡片停用，新卡七個工作天寄到，爭議款由銀行處理。他說我可以掛掉電話，打卡片背面的客服再確認，也能在銀行 App 的交易明細看到這筆。我打開銀行 App 查明細。', '[{"tag": null, "text": "只核對交易是不是本人，由銀行停卡並處理爭議款"}, {"tag": null, "text": "讓你掛掉電話自己打卡片背面的客服確認"}]'::jsonb, 2, '{1058}'::bigint[], '依據：金管會新聞稿「提醒民眾防範信用卡遭詐騙盜刷」', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-06'), 'published', 'exam_message', 'atm-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-08', 'atm', false, '家具尾款的戶名核對', '我用行動銀行付家具配送尾款，轉帳前畫面顯示的受款戶名，和契約上的公司名稱有幾個字不同。我先不送出，打給契約上印的家具行電話。店員說收款帳戶登記在母公司名下，所以戶名不一樣，他把母公司的名稱念給我，也把蓋有公司章的付款說明寄到我的信箱。店員說若還有疑問可以到門市看契約正本。我再看一次轉帳畫面上的隱碼戶名，和付款說明對得上。', '[{"tag": null, "text": "打契約上印的電話向店家確認戶名"}, {"tag": null, "text": "付款說明蓋有公司章，與轉帳畫面的戶名一致"}]'::jsonb, 3, '{1058}'::bigint[], '依據：金管會新聞稿「金管會提醒民眾轉帳時核對受款人戶名，並注意防範詐騙」', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-08'), 'published', 'exam_message', 'atm-08', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-09', 'atm', false, '門號的停用通知', '我收到一則通知，說我的門號 SIM 卡已經停用，新卡正在處理。我想起昨天在原本用的電信 App 申請了遺失補卡，App 案件頁上的申請時間和我操作的時間一樣。補卡要繳一點手續費，可以在 App 裡付，新卡可以選到門市拿或寄到家裡，我選了到門市拿。通知裡沒有連結，只寫了查詢的方式。我打開 App 的案件頁看進度。', '[{"tag": null, "text": "停用通知對應自己在電信 App 申請的補卡"}, {"tag": null, "text": "手續費在 App 裡繳，進度在案件頁查得到"}]'::jsonb, 1, '{1058}'::bigint[], '依據：電信業者 SIM 卡遺失補發與站內案件查詢流程', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-09'), 'published', 'exam_message', 'atm-09', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-11', 'atm', false, '教育基金會的獎助金', '我申請了一個民間教育基金會的獎助金，承辦人傳來核定通知，說可以領約六萬元。通知請我在基金會網站的申請系統上傳本人存摺封面影本和在學證明，下個月十號前上傳，撥款會直接匯進我本人的帳戶。我打基金會網站上公布的電話確認，接電話的人查到我的申請編號，說資料上傳後兩週內撥款。系統也列出審核中、已核准、已撥款三個狀態。我正在掃描存摺封面。', '[{"tag": null, "text": "資料在基金會網站的申請系統上傳"}, {"tag": null, "text": "獎助金直接匯進本人帳戶，可打網站公布的電話確認"}]'::jsonb, 1, '{1058}'::bigint[], '依據：民間獎助學金之申請、資料審核與撥款作業', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-11'), 'published', 'exam_message', 'atm-11', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-05', 'atm', false, '攝影方案的分期設定', '我預訂了一套婚禮攝影方案，晚上有自稱攝影平台客服的人打來，報得出方案和大約的價格，說付款被誤設成分六期，想確認我原本是不是選一次付清。我說是一次付清，他說會在後台改回來，改好後 App 會發通知，信用卡帳單也只會出現一筆。他說我不放心的話，可以掛掉電話，從 App 的客服頁找他們。我打開 App 的站內訊息。', '[{"tag": null, "text": "在後台改回付款設定，不需要我做任何操作"}, {"tag": null, "text": "案件會出現在 App 的站內訊息，可以自己查"}]'::jsonb, 1, '{1058}'::bigint[], '依據：團隊整理的正規流程說明「訂單問題正規客服處理流程」與金管會信用卡安全提醒', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-05'), 'published', 'exam_scenario', 'atm-03', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
INSERT INTO game_cases (case_key, fraud_type, is_scam, title, narrative, red_flags, difficulty, source_document_ids, provenance, mirror_of, status, pool, pattern_key, published_at) VALUES ('atm-exam-legit-10', 'atm', false, '停車年費的扣款照會', '我收到一則停車服務年費的交易訊息，可是我不記得有申辦。我打開發卡銀行的 App，在交易明細看到同一筆待確認的款項，App 請我選擇是不是本人交易。我選了不是本人，系統暫停這張卡、建立了爭議案件，案件頁列出這筆款項怎麼處理，也寫了可以打卡片背面的電話確認。我正在對自己這幾個月的停車紀錄，確認有沒有申辦過。', '[{"tag": null, "text": "在發卡銀行的 App 確認是不是本人交易"}, {"tag": null, "text": "選非本人後，銀行停卡並建立爭議案件"}]'::jsonb, 2, '{1058}'::bigint[], '依據：金管會信用卡安全提醒與發卡銀行爭議款處理流程', (SELECT id FROM game_cases WHERE case_key = 'atm-exam-scam-10'), 'published', 'exam_scenario', 'atm-06', now()) ON CONFLICT (case_key) DO UPDATE SET fraud_type = EXCLUDED.fraud_type, is_scam = EXCLUDED.is_scam, title = EXCLUDED.title, narrative = EXCLUDED.narrative, red_flags = EXCLUDED.red_flags, difficulty = EXCLUDED.difficulty, source_document_ids = EXCLUDED.source_document_ids, provenance = EXCLUDED.provenance, mirror_of = EXCLUDED.mirror_of, status = EXCLUDED.status, pool = EXCLUDED.pool, pattern_key = EXCLUDED.pattern_key, published_at = EXCLUDED.published_at;
